import { useEffect, useRef, useState } from "react";
import { FileUp, LoaderCircle, X } from "lucide-react";
import {
  cloudAccount,
  cloudAvailable,
  uploadDocumentToCloud,
} from "../../lib/cloudDocuments";
import {
  DOCUMENT_ACCEPT,
  DOCUMENT_ROW_FULL_MESSAGE,
  DOCUMENT_ROW_LIMIT,
  documentRowFull,
  documentSizeLabel,
  guardDocumentFile,
} from "../../lib/documentLibrary";
import { useDocuments } from "../../store/documents";
import { useLeafia } from "../../store/leafia";
import { CloudAuthForm } from "./CloudBackupPanel";
import "./documents.css";

/**
 * 导入文档：选文件 → 问存哪儿（只存本机 / 顺便备份到云端）→ 解析入库。
 *
 * 解析（pdfjs / mammoth / jszip）放在「导入」那一下做，读不出文本的文件
 * 不会先占掉一个书架位。
 */
export function ImportDocumentDialog({
  open,
  onClose,
  onImported,
}: {
  open: boolean;
  onClose: () => void;
  onImported?: (title: string) => void;
}) {
  const showToast = useLeafia((state) => state.showToast);
  const importFile = useDocuments((state) => state.importFile);
  const patchCloud = useDocuments((state) => state.patchCloud);
  const documents = useDocuments((state) => state.documents);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [file, setFile] = useState<File | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [warnings, setWarnings] = useState<string[]>([]);
  const [target, setTarget] = useState<"local" | "cloud">("local");
  const [email, setEmail] = useState<string | null>(null);
  const [stage, setStage] = useState<"idle" | "reading" | "uploading">("idle");
  const [dragging, setDragging] = useState(false);

  useEffect(() => {
    if (!open) return;
    setFile(null);
    setError(null);
    setWarnings([]);
    setStage("idle");
    setTarget("local");
    void cloudAccount().then((account) => setEmail(account?.email ?? null));
  }, [open]);

  if (!open) return null;

  const configured = cloudAvailable();
  const signedIn = Boolean(email);

  const choose = (picked: File | null | undefined) => {
    if (!picked) return;
    const guard = guardDocumentFile(picked.name);
    if (!guard.ok) {
      setFile(null);
      setError(guard.message);
      return;
    }
    setFile(picked);
    setError(null);
    setWarnings([]);
  };

  const run = async () => {
    if (!file || stage !== "idle") return;
    if (target === "cloud" && !signedIn) {
      setError("先登录备份账号，再勾「同时备份到云端」。");
      return;
    }
    setError(null);
    setStage("reading");
    try {
      // 这一下只把原文件收进这台浏览器 —— 正文在后台抽，不挡窗口。
      const { doc } = await importFile(file);
      let cloudNote = "";
      if (target === "cloud") {
        setStage("uploading");
        const blob = await useDocuments.getState().readBlob(doc.id);
        if (blob) {
          const uploaded = await uploadDocumentToCloud(doc, blob);
          if (uploaded.ok) {
            patchCloud(doc.id, {
              status: "uploaded",
              path: uploaded.value.path,
              uploadedAt: new Date().toISOString(),
            });
          } else {
            patchCloud(doc.id, { status: "failed", error: uploaded.message });
            cloudNote = `；云端备份没成功：${uploaded.message}`;
          }
        }
      }
      showToast(`已导入《${doc.title}》，正文正在本机解析${cloudNote}。`);
      onImported?.(doc.title);
      setStage("idle");
      onClose();
    } catch (importError) {
      setStage("idle");
      setError(
        importError instanceof Error ? importError.message : "导入失败，换个文件再试。",
      );
    }
  };

  const full = documentRowFull(documents.length);

  return (
    <div
      className="doc-modal"
      role="presentation"
      onClick={() => stage === "idle" && onClose()}
    >
      <div
        className="doc-dialog"
        role="dialog"
        aria-modal="true"
        aria-label="导入文档"
        onClick={(event) => event.stopPropagation()}
      >
        <header>
          <div>
            <span>Import document</span>
            <h2>导入文档</h2>
          </div>
          <button
            type="button"
            className="doc-button doc-button--quiet"
            aria-label="关闭"
            onClick={onClose}
            disabled={stage !== "idle"}
          >
            <X size={17} />
          </button>
        </header>

        <div className="doc-dialog__body">
          <div
            className={`doc-drop${dragging ? " is-over" : ""}`}
            onDragOver={(event) => {
              event.preventDefault();
              setDragging(true);
            }}
            onDragLeave={() => setDragging(false)}
            onDrop={(event) => {
              event.preventDefault();
              setDragging(false);
              choose(event.dataTransfer.files?.[0]);
            }}
          >
            <FileUp size={22} />
            <strong>{file ? file.name : "把文件拖进来，或点下面选一个"}</strong>
            <small>
              收 PDF / DOCX / PPTX / EPUB，都在浏览器里本地解析，不上传服务器。
            </small>
            <input
              ref={fileInputRef}
              type="file"
              accept={DOCUMENT_ACCEPT}
              hidden
              onChange={(event) => {
                choose(event.target.files?.[0]);
                event.target.value = "";
              }}
            />
            <button
              type="button"
              className="doc-button"
              onClick={() => fileInputRef.current?.click()}
            >
              选择文件
            </button>
          </div>

          <p className="doc-note doc-note--warn">
            旧版 .ppt / .doc 解析效果差，建议先在 PowerPoint / Word 里另存为
            .pptx / .docx 再导入。
          </p>

          <div className="doc-choice">
            <label className={target === "local" ? "is-selected" : ""}>
              <input
                type="radio"
                name="doc-target"
                checked={target === "local"}
                onChange={() => setTarget("local")}
              />
              <span>
                <strong>只存本机（默认）</strong>
                <small>
                  存进这台浏览器的 IndexedDB，不上传云端；换设备或清浏览器数据后就没了。
                </small>
              </span>
            </label>
            <label
              className={[
                target === "cloud" ? "is-selected" : "",
                configured ? "" : "is-disabled",
              ]
                .filter(Boolean)
                .join(" ")}
            >
              <input
                type="radio"
                name="doc-target"
                checked={target === "cloud"}
                disabled={!configured}
                onChange={() => setTarget("cloud")}
              />
              <span>
                <strong>存本机，并备份到云端</strong>
                <small>
                  {configured
                    ? "原文件也存一份到云端你自己的账号，换设备登录备份账号就能恢复。"
                    : "这份构建没有配云端，备份不可用。"}
                </small>
              </span>
            </label>
          </div>

          {target === "cloud" && configured && !signedIn && (
            <CloudAuthForm onSignedIn={(next) => setEmail(next)} />
          )}
          {target === "cloud" && signedIn && (
            <p className="doc-note">将备份到 {email}。</p>
          )}

          {file && (
            <p className="doc-note">
              待导入：《{file.name}》 · {documentSizeLabel({ size: file.size })}
            </p>
          )}
          {full && (
            <p className="doc-note doc-note--warn">{DOCUMENT_ROW_FULL_MESSAGE}</p>
          )}
          {error && <p className="doc-note doc-note--error">{error}</p>}
          {warnings.map((warning) => (
            <p className="doc-note doc-note--warn" key={warning}>
              {warning}
            </p>
          ))}
          {stage !== "idle" && (
            <p className="doc-busy">
              <LoaderCircle size={15} className="doc-spin" />
              {stage === "reading"
                ? "正在把文件存进这台浏览器…"
                : "正在备份到云端…"}
            </p>
          )}
        </div>

        <footer>
          <button
            type="button"
            className="doc-button doc-button--quiet"
            onClick={onClose}
            disabled={stage !== "idle"}
          >
            取消
          </button>
          <button
            type="button"
            className="doc-button doc-button--primary"
            onClick={() => void run()}
            disabled={!file || stage !== "idle" || full}
          >
            {stage === "idle" ? "导入" : "处理中…"}
          </button>
        </footer>
      </div>
    </div>
  );
}
