import { useEffect, useState } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import {
  ArrowLeft,
  BookOpen,
  CloudUpload,
  FileUp,
  LoaderCircle,
  Trash2,
} from "lucide-react";
import {
  cloudAccount,
  cloudAvailable,
  uploadDocumentToCloud,
} from "../../lib/cloudDocuments";
import {
  DOCUMENT_ROW_FULL_MESSAGE,
  DOCUMENT_ROW_LIMIT,
  documentBookId,
  documentCloudLabel,
  documentRowFull,
  documentSizeLabel,
  documentTextState,
} from "../../lib/documentLibrary";
import { useDocuments } from "../../store/documents";
import { useLeafia } from "../../store/leafia";
import { CloudBackupPanel } from "./CloudBackupPanel";
import { ImportDocumentDialog } from "./ImportDocumentDialog";
import "./documents.css";

/**
 * 我的文档：导入的文档都在这儿，也正是书架 04 那一排。
 * 导入的位置（本机 / 本机 + 云端）在导入对话框里选，这一页负责清点、
 * 打开、备份、删除，以及把免责那句话说清楚。
 */
export function DocumentsPage() {
  const navigate = useNavigate();
  const showToast = useLeafia((state) => state.showToast);
  const [searchParams, setSearchParams] = useSearchParams();
  const documents = useDocuments((state) => state.documents);
  const parse = useDocuments((state) => state.parse);
  const hydrate = useDocuments((state) => state.hydrate);
  const removeDocument = useDocuments((state) => state.removeDocument);
  const patchCloud = useDocuments((state) => state.patchCloud);
  const [importOpen, setImportOpen] = useState(
    () => searchParams.get("import") === "1",
  );
  const [busyId, setBusyId] = useState<string | null>(null);

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  const closeImport = () => {
    setImportOpen(false);
    if (searchParams.get("import")) {
      const next = new URLSearchParams(searchParams);
      next.delete("import");
      setSearchParams(next, { replace: true });
    }
  };

  const backup = async (id: string) => {
    const doc = documents.find((entry) => entry.id === id);
    if (!doc) return;
    if (!cloudAvailable()) {
      showToast("这份构建没配云端，备份用不了。");
      return;
    }
    const account = await cloudAccount();
    if (!account) {
      showToast("先在下面「云端备份」里登录备份账号。");
      return;
    }
    setBusyId(id);
    const blob = await useDocuments.getState().readBlob(id);
    if (!blob) {
      setBusyId(null);
      patchCloud(id, { status: "failed", error: "本机找不到原文件。" });
      showToast("本机找不到这份文件的原件，重新导入一次再备份。");
      return;
    }
    const uploaded = await uploadDocumentToCloud(doc, blob);
    setBusyId(null);
    if (uploaded.ok) {
      patchCloud(id, {
        status: "uploaded",
        path: uploaded.value.path,
        uploadedAt: new Date().toISOString(),
      });
      showToast(`《${doc.title}》已备份到云端。`);
    } else {
      patchCloud(id, { status: "failed", error: uploaded.message });
      showToast(uploaded.message);
    }
  };

  const full = documentRowFull(documents.length);

  return (
    <article className="doc-page">
      <header className="doc-page__header">
        <button
          type="button"
          className="doc-button doc-button--quiet"
          onClick={() => navigate("/shelf")}
        >
          <ArrowLeft size={15} />
          返回书架
        </button>
        <span className="eyebrow">My documents · 书架第四层</span>
        <h1>我的文档</h1>
        <p>
          自己导入的 PDF / Word / PPT / EPUB 都在这里，书架上第四层那一排就是它们。
          文档默认只存在这台浏览器里；要跨设备，就登录备份账号把它备份到云端。
        </p>
        <div className="doc-page__actions">
          <button
            type="button"
            className="doc-button doc-button--primary"
            onClick={() => setImportOpen(true)}
            disabled={full}
          >
            <FileUp size={15} />
            导入文档
          </button>
          <span className="doc-note">
            {documents.length} / {DOCUMENT_ROW_LIMIT} 本
            {full ? ` · ${DOCUMENT_ROW_FULL_MESSAGE}` : ""}
          </span>
        </div>
      </header>

      <section className="doc-card">
        <header>
          <h2>本机文档</h2>
          <small>Local · 浏览器 IndexedDB</small>
        </header>
        <ul className="doc-list">
          {documents.length === 0 && (
            <li className="doc-list__row is-empty">
              还没有文档：点上面的「导入文档」，PDF、Word、PPT、EPUB 都可以。
            </li>
          )}
          {documents.map((doc) => {
            const progress = parse[doc.id];
            const parsing = documentTextState(doc) === "parsing";
            return (
            <li className="doc-list__row" key={doc.id}>
              <div className="doc-list__main">
                <strong>{doc.title}</strong>
                <small>
                  {parsing ? (
                    <>
                      正文解析中
                      {progress ? ` ${progress.page} / ${progress.total} 页` : "…"}
                    </>
                  ) : (
                    <>
                      {doc.fileType} · {documentSizeLabel(doc)}
                      {doc.pages ? ` · ${doc.pages} 页` : ""} ·{" "}
                      {new Date(doc.createdAt).toLocaleDateString("zh-CN")}
                    </>
                  )}
                </small>
                {!parsing && doc.textNote ? (
                  <small className="doc-list__note">{doc.textNote}</small>
                ) : null}
              </div>
              <span
                className={
                  doc.cloud.status === "uploaded"
                    ? "doc-tag"
                    : doc.cloud.status === "failed"
                      ? "doc-tag doc-tag--warn"
                      : "doc-tag doc-tag--muted"
                }
              >
                {documentCloudLabel(doc)}
              </span>
              <button
                type="button"
                className="doc-button"
                onClick={() => navigate(`/book/${documentBookId(doc.id)}`)}
              >
                <BookOpen size={15} />
                阅读
              </button>
              <button
                type="button"
                className="doc-button"
                disabled={busyId === doc.id}
                onClick={() => void backup(doc.id)}
              >
                {busyId === doc.id ? (
                  <LoaderCircle size={15} className="doc-spin" />
                ) : (
                  <CloudUpload size={15} />
                )}
                {doc.cloud.status === "uploaded" ? "重新备份" : "备份到云端"}
              </button>
              <button
                type="button"
                className="doc-button doc-button--quiet doc-button--danger"
                onClick={() => {
                  void removeDocument(doc.id).then(() => {
                    showToast(`已从本机删除《${doc.title}》。`);
                  });
                }}
              >
                <Trash2 size={15} />
                删除
              </button>
            </li>
            );
          })}
        </ul>
        {documents.some((doc) => doc.cloud.status === "failed") && (
          <p className="doc-note doc-note--warn">
            有文档的云端备份没成功，鼠标停在那一行的说明上能看到原因；稍后点
            「重新备份」再试。
          </p>
        )}
      </section>

      <CloudBackupPanel />

      <p className="doc-disclaimer">
        免责说明：导入的文档保存在当前浏览器本地，也可以手动备份到你自己的云端
        账号；它们不会被上传到 Leafia 的服务器，也不会被其他人看到。文档的版权
        与内容合规由导入者自行负责 —— 请只导入你有权使用的材料。
      </p>

      <ImportDocumentDialog open={importOpen} onClose={closeImport} />
    </article>
  );
}
